#!/usr/bin/env bash
# Replace the hunks of auto-generated files in a diff with a one-line message.
# Run from the repository root (generated Java files are detected by reading them).
# Usage: git diff | .claude/scripts/mask-diff.sh
#
# Example output:
#   diff --git a/uv.lock b/uv.lock
#   index 1111111..2222222 100644
#   --- a/uv.lock
#   +++ b/uv.lock
#   Auto-generated file, diff omitted
set -euo pipefail

awk '
function generated(path,  first, status) {
  if (path ~ /^mlflow\/protos\/.*\.pyi?$/) return 1
  if (path ~ /(^|\/)(uv\.lock|yarn\.lock|package-lock\.json)$/) return 1
  if (path !~ /\.java$/) return 0
  status = (getline first < path); close(path)
  return status > 0 && first ~ /Generated by the protocol buffer compiler/
}
/^diff --git / {
  path = $0; sub(/.* b\//, "", path)
  mask = generated(path)
  header = 1
}
/^@@/ { if (mask && header) print "Auto-generated file, diff omitted"; header = 0 }
header || !mask
'
